"use client";

import { AnimatePresence, motion } from "motion/react";
import { useId, useState } from "react";

export function NumberStepperTailwind({ min = 0, max = 12 }) {
  const id = useId();
  const [value, setValue] = useState(2);
  const [dir, setDir] = useState(1);
  const set = (n: number) => { const v = Math.min(max, Math.max(min, n)); setDir(v > value ? 1 : -1); setValue(v); };
  return (
    <div className="inline-flex flex-col gap-2 text-zinc-100">
      <span id={id} className="text-sm font-medium">Guests</span>
      <div className="inline-flex h-11 items-center gap-1 rounded-xl border border-zinc-800 bg-zinc-900 px-1 focus-within:ring-4 focus-within:ring-indigo-500/25">
        <button type="button" tabIndex={-1} aria-label="Decrease Guests" disabled={value <= min} onClick={() => set(value - 1)} className="size-9 rounded-lg border border-zinc-800 bg-zinc-950 disabled:opacity-35">−</button>
        <div role="spinbutton" tabIndex={0} aria-labelledby={id} aria-valuenow={value} aria-valuemin={min} aria-valuemax={max} onKeyDown={(e) => { if (e.key === "ArrowUp") set(value + 1); if (e.key === "ArrowDown") set(value - 1); }} className="relative grid h-full min-w-16 place-items-center overflow-hidden text-xl font-semibold tabular-nums outline-none">
          <AnimatePresence initial={false} mode="popLayout" custom={dir}>
            <motion.span key={value} custom={dir} initial={{ y: `${dir * 70}%`, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: `${dir * -70}%`, opacity: 0 }}>{value}</motion.span>
          </AnimatePresence>
        </div>
        <button type="button" tabIndex={-1} aria-label="Increase Guests" disabled={value >= max} onClick={() => set(value + 1)} className="size-9 rounded-lg border border-zinc-800 bg-zinc-950 disabled:opacity-35">+</button>
      </div>
    </div>
  );
}
